@evento("consultor", "📊 Um consultor bate à porta", "Recebeu um e-mail: 'Posso triplicar sua margem'…",
        cond=lambda e: e["mes"] > 4, peso=0.8, cooldown=14)
def _(e):
    p = pessoa(e, "consultor")
