def casa_final_discurso_npc(e, x):
    """Discurso de quem é finalista: com a IA, nasce do que a pessoa viveu na casa; sem ela, uma frase que ninguém mais da final usou."""
    p = e["parts"][x]
    usados = e.setdefault("discursos_usados", [])
    if S.get("groq_key"):
        try:
            r = e.get("rodada") or {}
            d0 = (e.get("papos") or {}).get(x) or {}
            d = json.loads(groq_chat([{"role": "system", "content": casa_agente_base(e, x) +
                f"É a GRANDE FINAL. Diga ao público por que você merece o prêmio de um milhão, em 2 frases curtas (até 35 palavras), do seu jeito, citando algo SEU: "
                f"a sua história, o assunto que você trouxe ({CASA_PAPO_TIPOS[r['tipos'][x]][1] if x in r.get('tipos', {}) else 'a convivência'}), "
                f"a conversa com {e['jogador']} (foi {'ótima' if d0.get('nota', 5) >= 7.5 else 'boa' if d0.get('nota', 5) >= 5.5 else 'difícil'}) ou o seu sonho. "
                "Não copie frases de ninguém, não repita o que outros finalistas disseram: " + " | ".join(usados) +
                "\nResponda SOMENTE JSON: {\"discurso\": \"...\"}"}, {"role": "user", "content": "(a plateia está em silêncio esperando)"}], json_mode=True))
            t = casa_sem_beijo(str(d.get("discurso", "")).strip()[:260])
            if len(t) > 25 and t not in usados and t != (e.get("defesa", {}).get("eu", {}) or {}).get("txt"):
                usados.append(t)
                return casa_gen(e, t, x)
        except Exception:
            pass
    t = casa_gen(e, CASA_FINAL_NPC.get(p["perso"], "Eu mereço porque dei tudo de mim nessa casa."), x)
    if p["sexo"] == "F":
        t = t.replace("verdadeiro", "verdadeira").replace("o mais quieto", "a mais quieta").replace("o melhor jogador", "a melhor jogadora")
    else:
        t = t.replace("eu mesma", "eu mesmo")
    if t in usados or any(t[:40] == u[:40] for u in usados):   # dois finalistas com o mesmo jeito: o segundo fala outra coisa
        t = casa_gen(e, random.choice([u for u in CASA_FINAL_NPC_EXTRA if u not in usados] or CASA_FINAL_NPC_EXTRA), x)
        if p["sexo"] == "F":
            t = t.replace("perfeito", "perfeita").replace("inteiro", "inteira")
    usados.append(t)
    sonho = (p.get("ficha") or {}).get("sonho")
    return t + (f" E esse prêmio vai me ajudar a {sonho}." if sonho else " Esse prêmio vai mudar a minha vida.")


def casa_final_iniciar(e, fin):
    """Monta a cena da final na frente da casa: discursos, votação da plateia, apuração e o cheque."""
    ordem, votos, cont = casa_voto_publico(e, fin)
    e["voto_pub"] = dict(ordem=ordem, votos=votos, cont=cont, fin=fin)
    nomes = [e["jogador"] if x == "eu" else casa_nome(e, x) for x in fin]
    disc = []
    for i, x in enumerate(fin):   # o robô fala primeiro e você por último
        if x != "eu":
            disc.append(dict(i=i, nome=nomes[i], texto=casa_final_discurso_npc(e, x), sexo=e["parts"][x]["sexo"], h=sum(map(ord, nomes[i]))))
    if "eu" in fin:
        disc.append(dict(i=fin.index("eu"), nome=e["jogador"] + " (você)", texto=e["defesa"].get("eu", {}).get("txt", "Obrigado, Brasil!"), sexo=e["sexo"],
                         h=sum(map(ord, e["jogador"]))))
    cv = casa_convites_gerar(e, ordem[0])
    e["voto_pub"]["convites"] = cv
    casa_cena(e, "saida_rua", [x for x in fin if x != "eu"], "", titulo="🏆 A GRANDE FINAL", capitulo="Na frente da casa", enc="votopub", eu="eu" in fin,
              extra=dict(votoPub=dict(nomes=nomes, votos=[fin.index(v) + 1 for v in votos], discursos=disc, convites=cv["fala"])), maxn=3)
    e.setdefault("replay", {})["🏆 A grande final e a votação do público"] = dict(e["cena"])
    dur = lambda t: max(4.2, len(t)*.072) + .9
    intro = "Agora quem decide é o público! " + " ".join(f"Para votar em {n}, placa {i + 1}." for i, n in enumerate(nomes)) + " Valendo!"
    n = len(votos)
    e["play_ate"] = (time.time() + .9 + dur("Chegamos à grande final! Antes do público votar, os finalistas têm a palavra.") + sum(dur(d["texto"]) for d in disc) + dur(intro)
                     + sum(.95 if r < .15 else .42 if r < .6 else .26 if r < .85 else .6 for r in [(k + 1)/n for k in range(n)])
                     + 18.6 + max(10, dur(cv["fala"]) + 2))   # cheque, 6 s comemorando, 10 s de plateia, os convites do apresentador, e só então a tela de compartilhar


def casa_convites_gerar(e, w):
    """Os convites que o apresentador anuncia na frente da casa: capa da revista, marca de moda e entrevista na TV Meus Agentes de IA."""
    nw = e["jogador"] if w == "eu" else casa_nome(e, w)
    rng = random.Random(f"{nw}{len(e.get('diario', []))}")
    emp, marca = rng.choice(CASA_EMPRESARIAS)
    progs = rng.sample(CASA_PROGRAMAS, 3)
    rev = CASA_REVISTA
    fala = (f"{nw}, parabéns! E não acabou: você vai ser capa da revista {rev}, e a {marca} quer você como o novo rosto da coleção! "
            f"E a {CASA_TV} te convida para uma entrevista exclusiva, para contar como foi a sua experiência com o Meus Agentes de IA: "
            f"usar todas as ferramentas, criar vídeos com os agentes e colocar a automação para trabalhar por você. Brasil, aplausos para {nw}!")
    return dict(empresaria=emp, marca=marca, diretor="Apresentador", programas=progs, revista=rev, tv=CASA_TV, entrevista=CASA_ENTREVISTA_TEMA, fala=fala)


