def casa_criador():
    """Monta o personagem do jogador: corpo, rosto, roupa, origem e o vídeo de apresentação."""
    sx = st.radio("Você é", ["Homem", "Mulher"], horizontal=True, key="cs_sexo")
    F = sx == "Mulher"
    S.setdefault("cs_look_base", casa_look_jogador("F" if F else "M", random.Random()))
    base = S["cs_look_base"]
    if base.get("sexo") != ("F" if F else "M"):
        base = S["cs_look_base"] = casa_look_jogador("F" if F else "M", random.Random())
    sk = "F" if F else "M"   # chaves separadas por sexo: trocar de sexo não deixa opção do outro sexo presa
    t1, t2, t3 = st.tabs(["👤 Quem é você", "🎨 Visual", "🎬 Sua apresentação"])
    with t1:
        c1, c2 = st.columns(2)
        nome = c1.text_input("Nome na casa", value=S.get("usuario", "") or "", key="cs_nome", max_chars=20)
        idade = c2.slider("Idade", 18, 65, 27, key="cs_idade")
        c1, c2 = st.columns(2)
        cidade = c1.text_input("Sua cidade", key="cs_cidade", max_chars=40, placeholder="ex.: Betim (MG)").strip()
        prof = c2.text_input("Profissão", value="", key="cs_prof", placeholder="ex.: motorista de aplicativo")
        hobby = st.text_input("O que você gosta de fazer", key="cs_hob", placeholder="ex.: jogar bola, dançar forró")
    with t2:
        opc = lambda rot, d, atual, key: st.selectbox(rot, list(d), index=list(d).index(atual) if atual in d else 0, format_func=d.get, key=key)
        c1, c2, c3 = st.columns(3)
        with c1:
            pele = opc("Tom de pele", CASA_PELE_N if F else CASA_PELE_M, base["pele"], "cs_pele" + sk)
            corpo = opc("Corpo", CASA_CORPO_F if F else CASA_CORPO_M, base["corpo"], "cs_corpo" + sk)
            altura = opc("Altura", CASA_ALTURA_F if F else CASA_ALTURA_M, base.get("altura", 1.0), "cs_alt" + sk)
            olho = opc("Olhos", CASA_OLHOS, base.get("olho"), "cs_olho" + sk)
        with c2:
            cab = opc("Cabelo", CASA_CAB_F if F else CASA_CAB_M, base["cab"], "cs_cab" + sk)
            cab_cor = opc("Cor do cabelo", CASA_COR_CAB, base["cab_cor"], "cs_cabcor" + sk)
            barba = None if F else opc("Barba", {"": "Sem barba", "curta": "Curta", "cheia": "Cheia", "cavanhaque": "Cavanhaque", "bigode": "Bigode"}, base.get("barba") or "", "cs_barba" + sk) or None
        with c3:
            roupa = opc("Roupa", CASA_ROUPA_F if F else CASA_ROUPA_M, base["roupa"], "cs_roupa" + sk)
            cor = opc("Cor da roupa", CASA_CORES_ROUPA, base["cor"], "cs_cor" + sk)
            tat = opc("Tatuagem", CASA_TAT, "+".join(base.get("tat") or []), "cs_tat" + sk)
        ac_ok = ("brincos", "corrente", "oculos", "bone")
        acess = st.multiselect("Acessórios", list(ac_ok), default=[a for a in base.get("acess", []) if a in ac_ok],
                               format_func={"brincos": "💎 Brincos", "corrente": "📿 Corrente", "oculos": "🕶️ Óculos escuros", "bone": "🧢 Boné"}.get, key="cs_acess" + sk)
        if st.button("🎲 Sortear um visual", key="cs_sortear"):
            S["cs_look_base"] = casa_look_jogador("F" if F else "M", random.Random())
            for k2 in ("cs_pele", "cs_corpo", "cs_alt", "cs_olho", "cs_cab", "cs_cabcor", "cs_barba", "cs_roupa", "cs_cor", "cs_tat", "cs_acess"):
                st.session_state.pop(k2 + sk, None)
            st.rerun()
    look = dict(base, sexo="F" if F else "M", pele=pele, corpo=corpo, olho=olho, cab=cab, cab_cor=cab_cor, barba=barba, roupa=roupa, cor=cor, altura=altura,
                tat=[x for x in tat.split("+") if x], acess=acess, idade=idade, nome=nome or "Você")
    st.caption(("🙋‍♀️ Você: " if F else "🙋‍♂️ Você: ") + f"{(CASA_ALTURA_F if F else CASA_ALTURA_M)[altura].lower()}, {(CASA_PELE_N if F else CASA_PELE_M)[pele].lower()}, "
               f"{(CASA_CORPO_F if F else CASA_CORPO_M)[corpo].lower()}, cabelo {(CASA_CAB_F if F else CASA_CAB_M)[cab].lower()} {CASA_COR_CAB[cab_cor].lower()}"
               + (f", {('barba ' + barba) if barba not in ('cavanhaque', 'bigode') else barba}" if barba else "") + (", tatuada" if F else ", tatuado") * bool(look["tat"]) + ".")
    with t3:
        st.caption("Grave agora o seu vídeo de apresentação. Ele passa junto com o dos outros participantes, e o público forma a primeira impressão sobre você.")
        microfone_campo("cs_ap_mic", "cs_ap_txt")
        fala = st.text_area("Sua apresentação", key="cs_ap_txt", height=110,
                            placeholder=f"Oi, Brasil! Eu sou {nome or '...'}, tenho {idade} anos, sou de {(cidade or 'Betim').split(' (')[0]}... e vim pra...")
    st.markdown("**👀 Prévia do seu personagem**")
    palco_casa(dict(lugar="confessionario", enc="confessionario", foco=[], eu=look, fundo=[], local="🎬 Camarim", quem=None, titulo=None, texto="",
                    noite=False, host=CASA_HOST, vozFala=False), 300)
    return dict(nome=nome, sexo="F" if F else "M", idade=idade, cidade=cidade, prof=prof.strip() or ("estudante" if idade < 23 else "autônomo"),
                hobby=hobby.strip() or "curtir a vida", look=look, fala=fala)


def casa_cidade_da_fala(fala):
    """Se a pessoa não preencheu a cidade, usa a que ela disse na apresentação ('sou de Betim')."""
    import re
    m = re.search(r"\b(?:sou de|moro em|venho de|vim de|nasci em)\s+([A-ZÀ-Ú][\wÀ-ú'-]+(?:\s+(?:de|do|da|dos|das)?\s*[A-ZÀ-Ú][\wÀ-ú'-]+)*)", fala or "")
    return m.group(1).strip() if m else ""


def casa_setup():
    st.markdown(CSS_CASA, unsafe_allow_html=True)
    st.markdown("""<div class="casa-hero"><h2>🏠 A CASA DOS MEUS AGENTES IA</h2>
    <p><b>Um reality show em 3D onde todos os outros participantes são inteligências artificiais.</b></p>
    <p>Cada um tem personalidade, memória, amigos e inimigos. Eles conversam com você, fofocam, fazem alianças... e tentam te eliminar.</p>
    <p style="opacity:.75;font-size:.9rem">5 conversas em 5 cômodos · Emocionômetro · confessionário (saem 3) · final com 3 e voto do público</p></div>""",
                unsafe_allow_html=True)
    st.markdown("### 🧑‍🎤 Monte o seu participante")
    ficha = casa_criador()
    st.caption("🏠 Temporada com **6 participantes**: você e mais 5, **3 homens e 3 mulheres**. Você conversa com cada um, o confessionário tira 3 e os outros 3 vão para a final.")
    if st.button("🚪 Entrar na casa", type="primary", key="cs_entrar"):
        if not ficha["nome"].strip():
            st.error("Escolha um nome (aba 👤 Quem é você).")
            return
        if len((ficha["fala"] or "").strip()) < 15:
            st.error("Escreva ou grave a sua apresentação (aba 🎬 Sua apresentação).")
            return
        for k0 in [k0 for k0 in list(S.keys()) if isinstance(k0, str) and k0.startswith(("cs_fin", "cs_cf", "cs_rd", "cs_cr", "cs_share", "cs_json"))]:
            del S[k0]
        e = casa_nova(ficha["nome"].strip()[:20], ficha["sexo"], 5)
        for q in e.get("quartos", []):   # quem divide o quarto começa mais próximo
            a, b = q["membros"]
            casa_mudar(e, a, b, 10, 6)
            casa_mudar(e, b, a, 10, 6)
        jn, e["jogador"] = e["jogador"], ""
        casa_renomear(e, jn)
        e["look"] = dict(ficha["look"], nome=e["jogador"])
        cid = ficha["cidade"] or casa_cidade_da_fala(ficha["fala"]) or "Brasil"
        e["perfil_eu"] = dict(cidade=cid, prof=ficha["prof"], hobby=ficha["hobby"], idade=ficha["idade"], fala=ficha["fala"].strip())
        S["casa"] = e
        casa_reg(e, f"🚪 {e['jogador']} entrou na casa com mais {len(e['parts'])} participantes.")
        with st.spinner("Os participantes estão gravando as apresentações e o público está assistindo à sua..."):
            casa_perfis(e)
            nota, reac = casa_aval_defesa(e, ficha["fala"].strip())
        e["pop"] = casa_clamp(48 + (nota - 5)*3)
        if nota >= 8:
            casa_conquistar(e, "estrela")
        casa_reg(e, f"🎬 Sua apresentação recebeu nota {nota}/10 do público. {reac}")
        st.session_state["cs_ap_msg"] = f"🎬 Nota do público para a sua apresentação: **{nota}/10**. {reac} Sua popularidade inicial: **{e['pop']}**."
        S.pop("cs_look_base", None)
        e["fase"] = "apresentacao"
        e["apres_i"] = 0
        casa_apres_cena(e)
        st.rerun()
    if S.get("casa_album"):
        with st.expander(f"📒 Álbum de personagens ({len(S['casa_album'])}/{len(CASA_LENDAS)} conhecidos)"):
            casa_album_ui()
    with st.expander("📂 Reviver uma temporada salva"):
        st.caption("No fim de cada temporada dá para baixar um arquivo .json com tudo o que aconteceu. Envie esse arquivo aqui para rever o resultado, a sua jornada, o filme e as cenas marcantes.")
        casa_carregar_ui("cs_up_setup")
    if S.get("casa_conquistas"):
        with st.expander(f"🏅 Suas conquistas ({len(S['casa_conquistas'])}/{len(CASA_CONQ)})"):
            casa_conquistas_ui()
    vh = S.get("casa_hall", [])
    if vh:
        st.markdown("#### 🏛️ Suas temporadas")
        for h in vh[-5:][::-1]:
            st.markdown(f"• **{h['nome']}**: {h['res']} · {h['semanas']} semanas")


def casa_grupos_ui(e):
    nm = lambda x: casa_nome(e, x)
    st.markdown("#### 👥 Grupos e panelinhas")
    if not e["grupos"]:
        st.caption("Ainda não se formou nenhum grupo. Eles nascem sozinhos quando a amizade entre as pessoas cresce.")
    meu = casa_grupo_de(e, "eu")
    for g in e["grupos"]:
        st.markdown(f"**{g['emo']} {g['nome']}** · líder: {nm(g['lider'])} · {', '.join(('**Você**' if m == 'eu' else nm(m)) for m in g['membros'])}"
                    + (f" · 🎯 alvo: {nm(g['alvo'])}" if g.get("alvo") and (meu is g) else ""))
    if e["casais"]:
        st.markdown("**💑 Casais:** " + " · ".join(f"{nm(c['a'])} + {nm(c['b'])} (#{casa_ship(e, c['a'], c['b'])}{', em crise' if c['status'] == 'crise' else ''})" for c in e["casais"]))
    if e["traicoes"]:
        st.markdown("**🐍 Traições conhecidas:** " + " · ".join(f"S{t['semana']}: {nm(t['quem'])} ➜ {nm(t['contra'])}" for t in e["traicoes"][-5:]))
    if meu:
        k = f"cs_gr{e['semana']}"
        c1, c2 = st.columns(2)
        if meu["lider"] == "eu":
            cands = [x for x in casa_vivos(e) if x not in meu["membros"]]
            if cands:
                al = c1.selectbox("🎯 Alvo do seu grupo nesta semana", cands, format_func=nm, key=k + "alvo")
                if c1.button("Combinar o voto com o grupo", key=k + "alvob"):
                    meu["alvo"] = al
                    casa_reg(e, f"🎯 Seu grupo combinou votar em {nm(al)}.")
                    st.rerun()
        if c2.button(f"🚪 Sair do {meu['nome']}", key=k + "sair"):
            meu["membros"].remove("eu")
            for m in meu["membros"]:
                casa_mudar(e, m, "eu", -12, -18)
            casa_reg(e, f"🚪 Você saiu do grupo {meu['nome']}.")
            if len(meu["membros"]) < 2:
                e["grupos"].remove(meu)
            st.rerun()


def casa_relacoes(e):
    st.caption("O que cada um sente por **você**. As personalidades se revelam depois de duas conversas ou pelas câmeras.")
    vivos = sorted(casa_vivos(e, False), key=lambda x: -casa_op(e, x, "eu"))
    cols = st.columns(2)
    for i, pid in enumerate(vivos):
        p, r = e["parts"][pid], e["rel"][pid]["eu"]
        per = CASA_PERSO[p["perso"]][0] if p["revelado"] else "❔ personalidade desconhecida"
        cor = lambda v: "#43a047" if v >= 65 else "#e53935" if v <= 30 else "#fbc02d"
        pf = p.get("perfil") or {}
        cols[i % 2].markdown(f"""<div class="casa-card"><b>{p['nome']}</b>, {p['idade']} · {casa_rotulo(e, pid)}<br>
        <span style="font-size:.8rem;opacity:.8">{pf.get('prof', '')}{' de ' + pf['cidade'] if pf.get('cidade') else ''} · {casa_look_desc(p['look'])}</span><br><span style="opacity:.75;font-size:.85rem">{per}</span>
        <div style="font-size:.8rem">Amizade {r['amz']}/100</div><div class="casa-bar"><div style="width:{r['amz']}%;background:{cor(r['amz'])}"></div></div>
        <div style="font-size:.8rem">Confiança {r['conf']}/100</div><div class="casa-bar"><div style="width:{r['conf']}%;background:{cor(r['conf'])}"></div></div>
        {'<div style="font-size:.78rem;opacity:.7">🧠 ' + p['memoria'][-1] + '</div>' if p['memoria'] else ''}
        <div style="font-size:.78rem;opacity:.85">{(casa_grupo_de(e, pid)['emo'] + ' ' + casa_grupo_de(e, pid)['nome']) if casa_grupo_de(e, pid) else '👤 sem grupo'}{' · 💑 ' + casa_nome(e, casa_par(e, pid)) if casa_par(e, pid) else ''}{' · 🎯 ' + casa_obj_txt(e, pid) if pid in e['obj_vistos'] else ''}</div></div>""", unsafe_allow_html=True)
    casa_grupos_ui(e)
    if e["eliminados"]:
        st.caption("⚫ Eliminados: " + ", ".join(e["parts"][x]["nome"] for x in e["eliminados"]))


def casa_publico(e):
    st.caption("🌡️ Três termômetros: **popularidade** (o público lá fora), **respeito** (como a casa enxerga a pessoa) e **ameaça** (o quanto os outros acham que ela pode vencer).")
    linhas = ["| | Participante | ⭐ Popularidade | 🫡 Respeito | ⚠️ Ameaça |", "|---|---|---|---|---|"]
    for i, x in enumerate(sorted(casa_vivos(e), key=lambda x: -casa_popv(e, x)), 1):
        linhas.append(f"| {i}º | {'**Você**' if x == 'eu' else casa_nome(e, x)} | {casa_popv(e, x)} | {casa_respeito(e, x)} | {casa_ameaca(e, x)} |")
    st.markdown("\n".join(linhas))
    st.caption("Barras de popularidade:")
    tod = sorted(casa_vivos(e), key=lambda x: -casa_popv(e, x))
    for i, x in enumerate(tod, 1):
        v = casa_popv(e, x)
        tag = "💖 Queridinho" if v >= 70 else "🔥 Rejeitado" if v <= 32 else ""
        st.markdown(f"""<div style="display:flex;gap:8px;align-items:center"><div style="width:150px">{i}º <b>{'⭐ ' if x == 'eu' else ''}{casa_nome(e, x)}</b></div>
        <div class="casa-bar" style="flex:1"><div style="width:{v}%;background:linear-gradient(90deg,#7c4dff,#00e5ff)"></div></div>
        <div style="width:120px;font-size:.85rem">{v} {tag}</div></div>""", unsafe_allow_html=True)


def casa_diario(e):
    for sem, t in reversed(e["diario"][-60:]):
        st.markdown(f"**S{sem}** · {t}")


