def compartilhar_img_bytes():
    import base64
    return base64.b64decode(COMPARTILHAR_IMG_B64)


def compartilhar_ui(texto, key, titulo="📤 Compartilhar"):
    """Compartilhar com a imagem junto: no celular abre a lista do aparelho com a foto, o texto e o link;
    no computador baixa a foto e abre a rede escolhida com o texto pronto (a pessoa só anexa a imagem)."""
    from urllib.parse import quote
    url = app_url()
    msg = texto + (f" {url}" if url and url not in texto else "")
    st.markdown(f"**{titulo}**")
    ci, cb = st.columns([1, 2], vertical_alignment="center")
    ci.image(compartilhar_img_bytes(), use_container_width=True)
    ci.download_button("🖼️ Baixar a imagem", compartilhar_img_bytes(), file_name="casa-compartilhar.jpg", mime="image/jpeg", key=key + "_img", use_container_width=True)
    redes = [("whats", "🟢 WhatsApp", "#25d366", "https://wa.me/?text=" + quote(msg)),
             ("face", "📘 Facebook", "#1877f2", "https://www.facebook.com/sharer/sharer.php?u=" + quote(url or "")),
             ("insta", "📸 Instagram / TikTok", "#d62976", ""),
             ("tele", "✈️ Telegram", "#229ed9", "https://t.me/share/url?url=" + quote(url or " ") + "&text=" + quote(texto)),
             ("x", "✖️ X / Twitter", "#222", "https://twitter.com/intent/tweet?text=" + quote(msg))]
    botoes = "".join(f"<button data-r='{r}' data-u='{_html.escape(u, quote=True)}' style='background:{cor}'>{rot}</button>" for r, rot, cor, u in redes)
    with cb:
        jogo_html(f"""<!doctype html><html><head><meta charset='utf-8'><style>
body{{margin:0;font-family:system-ui;background:transparent;color:#8a8a99}}
#g{{display:grid;grid-template-columns:1fr 1fr;gap:7px}}
button{{padding:11px 6px;border:0;border-radius:10px;font-weight:800;font-size:14px;color:#fff;cursor:pointer}}
button:hover{{filter:brightness(1.12)}} #m{{font-size:12px;margin-top:7px;text-align:center;min-height:16px}}</style></head><body>
<div id='g'>{botoes}</div><div id='m'></div>
<script>
const TXT = {json.dumps(msg)};
const m = document.getElementById('m');
function arquivo(){{ const bin = atob("{COMPARTILHAR_IMG_B64}"); const arr = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return new File([arr], 'casa-compartilhar.jpg', {{type: 'image/jpeg'}}); }}
function baixar(f){{ const a = document.createElement('a'); a.href = URL.createObjectURL(f); a.download = f.name; document.body.appendChild(a); a.click(); a.remove(); }}
async function copiar(){{ for (const n of [(() => {{ try {{ return window.top.navigator; }} catch (e) {{ return null; }} }})(), navigator]) {{ try {{ if (n && n.clipboard) {{ await n.clipboard.writeText(TXT); return true; }} }} catch (e) {{}} }} return false; }}
const celular = /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
document.querySelectorAll('button').forEach(b => b.onclick = async () => {{
  const f = arquivo(), rede = b.dataset.r, link = b.dataset.u;
  // 1) celular: a lista de apps do aparelho, com a imagem anexada, o texto e o link
  if (celular) {{
    let N = navigator; try {{ if (window.top.navigator.share) N = window.top.navigator; }} catch (e) {{}}
    for (const nav of [N, navigator]) {{
      try {{ if (nav.canShare && nav.canShare({{files: [f]}})) {{ await nav.share({{files: [f], text: TXT}}); m.textContent = 'Compartilhado! 🎉'; return; }} }}
      catch (e) {{ if (e && e.name === 'AbortError') return; }}
    }}
  }}
  // 2) computador (ou celular sem esse recurso): baixa a imagem e abre a rede com o texto pronto
  baixar(f); const ok = await copiar();
  if (link) window.open(link, '_blank');
  m.textContent = rede === 'insta' ? 'Imagem baixada' + (ok ? ' e texto copiado' : '') + ': é só postar no Instagram ou TikTok e colar o texto.'
                                   : 'Imagem baixada' + (ok ? ' e texto copiado' : '') + ': anexe a imagem na mensagem que abriu.';
}});
</script></body></html>""", 150)
    with st.expander("📋 Texto para copiar"):
        st.code(msg, language=None)


def casa_texto_compartilhar(e):
    nm = e["jogador"]
    w = e.get("vencedor")
    pct = (e.get("final_pct") or {}).get(w)
    conq = len(e.get("conq", []))
    alb = len(S.get("casa_album", {}))
    if w == "eu":
        t = (f"🏆 Fui {'CAMPEÃ' if e['sexo'] == 'F' else 'CAMPEÃO'} d'A Casa dos Meus Agentes IA" + (f" com {pct}% dos votos do público" if pct else "")
             + "! Conversei com 5 participantes, sobrevivi ao confessionário e levei o cheque de R$ 1 milhão. 💸")
    elif w:
        nw = casa_nome(e, w)
        t = (f"🏠 Terminei em {e.get('colocacao')}º lugar n'A Casa dos Meus Agentes IA. Quem levou foi {nw}"
             + (f", com {pct}% dos votos" if pct else "") + ". Será que você vai mais longe?")
    else:
        t = ("🏠 Estou na casa mais vigiada do Brasil! N'A Casa dos Meus Agentes IA todo mundo é IA, menos eu: cinco conversas, um confessionário e só três chegam à final."
             " Venha conhecer!")
    if conq:
        t += f" 🏅 {conq} conquista{'s' if conq > 1 else ''} nesta temporada."
    if alb:
        t += f" 📒 Já conheci {alb} dos 30 personagens."
    return t + " Duvido você ganhar! 👀"


CASA_CONQ = {
    "estrela": ("🎬", "Estrela da estreia", "Tirou 8 ou mais na apresentação"),
    "papo_fogo": ("🔥", "A casa parou", "Tirou 9 ou mais no Emocionômetro numa resposta"),
    "querido": ("💖", "Queridinho da casa", "Fechou as 5 conversas com média 7,5 ou mais"),
    "conselheiro": ("🫶", "Ombro amigo", "Deu um conselho que mudou o dia de alguém"),
    "segredo": ("🔓", "Confidente", "Descobriu o maior segredo de um personagem"),
    "beijo": ("💋", "Clima no ar", "Deu um beijo dentro da casa"),
    "intocavel": ("🛡️", "Intocável", "Não recebeu nenhum voto no confessionário"),
    "final": ("🥉", "Finalista", "Chegou à final"),
    "campeao": ("🏆", "Campeão", "Venceu A Casa dos Meus Agentes IA"),
    "virada": ("🌟", "Virada histórica", "Venceu a final com menos de 6 de média nas conversas"),
}


def casa_conquistar(e, k):
    e.setdefault("conq", [])
    if k in e["conq"] or k not in CASA_CONQ:
        return
    e["conq"].append(k)
    todas = S.setdefault("casa_conquistas", {})
    novo = k not in todas
    todas[k] = todas.get(k, 0) + 1
    ic, t, _ = CASA_CONQ[k]
    casa_reg(e, f"🏅 Conquista: {ic} {t}")
    try:
        st.toast(f"🏅 Conquista{' nova' if novo else ''}: {ic} {t}")
    except Exception:
        pass


def casa_conquistas_ui(e=None):
    todas = S.get("casa_conquistas", {})
    st.caption(f"🏅 {len(todas)} de {len(CASA_CONQ)} conquistas desbloqueadas em todas as suas temporadas.")
    cols = st.columns(2)
    for i, (k, (ic, t, d)) in enumerate(CASA_CONQ.items()):
        tem = k in todas
        agora = e is not None and k in e.get("conq", [])
        cols[i % 2].markdown(f"<div class='casa-card' style='opacity:{1 if tem else .45}'>{ic if tem else '🔒'} <b>{t}</b>{' · 🆕 nesta temporada' if agora else ''}"
                             f"<br><span style='font-size:.8rem;opacity:.8'>{d}{' · ' + str(todas[k]) + 'x' if tem else ''}</span></div>", unsafe_allow_html=True)


# ---------- 📰 Plantão da Casa
CASA_MANCHETE = {"💥": "BARRACO! {q} solta o verbo", "🗣️": "Fofoca no quarto: {q} abre o jogo", "🕸️": "Nos bastidores, {q} arma o jogo", "💘": "Clima no ar entre {q} e {o}",
                 "💑": "É OFICIAL: {q} e {o} estão juntos", "😂": "{q} vira a alegria da casa", "⭐": "{q} reúne a galera na sala", "😔": "Sozinho no quarto: {q} se isola",
                 "🎯": "Na lata: {q} fala o que pensa", "💞": "Paz na casa: {q} e {o} se acertam", "💔": "Acabou: fim do casal {q} e {o}", "😤": "Ciúme! {q} não gostou nada",
                 "⚡": "Racha no grupo: {q} e {o} brigam", "🤝": "Proposta secreta: {q} quer virar o jogo", "📢": "Segredo exposto por {q}!", "😢": "{q} pensa em desistir",
                 "😮": "Reviravolta: {q} defende o rival", "🔄": "{q} muda tudo no jogo", "🌟": "Virada: {q} conquista a casa", "🍹": "Língua solta: {q} exagera na festa",
                 "🌡️": "Termômetro: o público mudou de lado"}


def casa_plantao(e, n=4, acao=False):
    evs = [ev for ev in e.get("eventos", []) if ev.get("semana") == e["semana"]][-n:][::-1]
    rot = "O QUE ROLOU NA CASA"
    if not evs:
        evs = [ev for ev in e.get("eventos_hist", []) if ev.get("semana") == e["semana"] - 1][-n:][::-1]
        rot = "O QUE ROLOU NA SEMANA PASSADA"
    if not evs:
        return
    nm = lambda x: e["jogador"] if x == "eu" else casa_nome(e, x)
    itens = []
    for ev in evs:
        q = ev.get("quem")
        outros = [x for x in ev.get("npcs", []) if x != q]
        mold = next((v for k2, v in CASA_MANCHETE.items() if ev["tipo"].startswith(k2)), "{q} movimenta a casa")
        tit = mold.format(q=nm(q) if q in e["parts"] or q == "eu" else "A casa", o=nm(outros[0]) if outros else "alguém")
        sub = casa_sem_voce(e, ev["texto"].replace("**", ""))
        itens.append(f"<div style='padding:6px 0;border-bottom:1px solid #2f2466'><div style='font-weight:900;font-size:1rem'>{tit}</div>"
                     f"<div style='font-size:.82rem;opacity:.8'>{sub}</div></div>")
    st.markdown("<div class='casa-card' style='border-color:#ff1744'><div style='font-size:.75rem;letter-spacing:2px;color:#ff5252;font-weight:900'>📰 PLANTÃO DA CASA · " + rot + "</div>"
                + "".join(itens) + "</div>", unsafe_allow_html=True)
    if not acao or e.get("fase") != "convivencia" or e.get("conversa"):
        return
    J = e["jogador"]
    comigo = []
    for ev in evs:
        q = ev.get("quem")
        if q in casa_vivos(e, False) and q not in comigo and (ev.get("contra_eu") or "você" in ev["texto"].lower() or J in ev["texto"]):
            comigo.append(q)
    for i, q in enumerate(comigo[:2]):
        if st.button(f"💬 Ir falar com {casa_nome(e, q)} sobre isso (não gasta ação)", key=f"cs_pl{e['semana']}_{e['acoes']}_{i}"):
            e["conversa"] = dict(pid=q, msgs=[], n=0, lugar="reality_sala", var=random.randrange(3), cen=casa_cenario_sortear(e, CASA_CEN_POR_TIPO["confronto"]))
            abre = casa_gen(e, random.choice([f"{J}... imaginei que você vinha falar comigo sobre aquilo.", f"Ah, {J}. Veio tirar satisfação, né? Pode falar.",
                                              f"Senta aqui, {J}. Bora conversar sobre o que aconteceu."]), q)
            e["conversa"]["msgs"].append(("npc", abre))
            e["_sem_variar"] = True
            casa_cena_conversa(e, q, abre, e["conversa"], titulo=f"💬 {casa_nome(e, q)} e {J}")
            st.rerun()


# ---------- 🛏️ Clima no quarto: quem divide o quarto com você puxa assunto (flerte, reclamação, pedido de ajuda, desabafo)
CASA_QUARTO_FALAS = {
    "flerte": ["Já vai dormir? Fica mais um pouquinho acordado(a) conversando comigo...", "Esse ar-condicionado tá um gelo. Divide o cobertor comigo?",
               "Dividir quarto com você tá sendo um perigo pro meu coração, sabia?", "Me dá um abraço antes de apagar a luz? Hoje eu tô precisando.",
               "Confessa: quando apaga a luz, você também fica pensando na gente?", "Você fica lindo(a) até com cara de sono, isso não é justo.",
               "Se a produção trocasse a gente de quarto, eu ia ficar bem chatead{o}..."],
    "reclama": ["Você ronca, sabia? Passei a noite inteira acordad{o} do seu lado!", "Quem largou a toalha molhada em cima da minha cama? Foi você, né?",
                "Dá pra apagar essa luz? Tem gente querendo dormir aqui!", "Você espalhou roupa pelo quarto inteiro de novo...",
                "Chegou de madrugada fazendo o maior barulho, hein? Me acordou!", "Pegou meu travesseiro de novo? Esse é o meu, o seu é o outro!"],
    "ajuda": ["Me ajuda? Não sei em quem votar essa semana e eu confio em você.", "Tô travad{o} pensando na prova de amanhã... me dá uma força?",
              "Acho que tão armando contra mim. Me ajuda a descobrir quem é?", "Me ajuda a escolher a roupa da festa? Você tem bom gosto.",
              "Tô brigad{o} com metade da casa. Me ajuda a fazer as pazes?"],
    "desabafo": ["Não consigo dormir... tô com uma saudade da minha família que dói.", "Posso te contar uma coisa que eu nunca falei pra ninguém aqui dentro?",
                 "Às vezes eu acordo de madrugada e acho que não vou aguentar até o fim.", "Que bom que eu caí no quarto com você. Aqui eu me sinto em casa."],
}


def casa_abordagem_quarto(e):
    q = casa_quarto_de(e, "eu")
    par = next((m for m in (q["membros"] if q else []) if m != "eu" and m in e["parts"] and e["parts"][m]["vivo"]), None)
    if not par:
        return None
    op = casa_op(e, par, "eu")
    pesos = {"flerte": 1 + max(0, op - 50)/8 + (2 if e["parts"][par]["perso"] == "sedutor" else 0) + (3 if casa_par(e, "eu") == par else 0),
             "reclama": 1 + max(0, 55 - op)/8 + (1.5 if e["parts"][par]["perso"] in ("explosivo", "arrogante", "sincero") else 0),
             "ajuda": 1.4 + (1 if par in e["aliados"] else 0), "desabafo": 1 + (1.5 if e["parts"][par]["perso"] in ("timido", "popular") else 0)}
    tipo = random.choices(list(pesos), weights=list(pesos.values()))[0]
    if casa_par(e, par) and casa_par(e, par) != "eu" and tipo == "flerte":
        tipo = "desabafo"
    fala = casa_escolher_fala(e, CASA_QUARTO_FALAS[tipo]).replace("{o}", "a" if e["parts"][par]["sexo"] == "F" else "o")
    return par, "q_" + tipo, fala


# ---------- 📩 Os agentes vêm falar com você
def casa_abordagem(e, chance=.5):
    if e.get("abordagem") or e.get("conversa") or e.get("abord_n", 0) >= 2 or random.random() > chance:
        return
    nm = lambda x: e["jogador"] if x == "eu" else casa_nome(e, x)
    J = e["jogador"]
    cand = []
    ult = e.setdefault("abord_ult", {})
    for x in casa_vivos(e, False):
        if ult.get(x, -9) >= e["semana"] - 1:
            continue
        p, r = e["parts"][x], e["rel"][x]["eu"]
        pk, o = p["perso"], e["objetivos"].get(x, {})
        rec = tuple(f"Semana {s0}:" for s0 in (e["semana"], e["semana"] - 1))
        mem = " ".join(m for m in p["memoria"] if m.startswith(rec)).lower()
        if f"{J.lower()} votou" in mem or "você votou" in mem or "indicado ao paredão por você" in mem:
            cand.append((3, x, "satisfacao", "A gente precisa conversar. Por que você votou em mim? Eu quero ouvir da sua boca."))
        if "você fez fofoca" in mem:
            cand.append((3, x, "satisfacao", "Me contaram o que você andou falando de mim. Vai negar na minha cara?"))
        if "recebeu sua placa" in mem or "confrontado por você" in mem:
            cand.append((2, x, "satisfacao", "Aquilo que você fez comigo na frente de todo mundo... eu não engoli. Bora conversar?"))
        if x in e["aliados"]:
            cand.append((1.6, x, "aliado", "Tô com medo dessa semana... Posso contar com você no voto? Preciso saber."))
        if o.get("tipo") == "conquistar" and o.get("alvo") == "eu":
            cand.append((2.5, x, "flerte", "Ei... posso sentar aqui com você? Faz dias que eu quero te conhecer melhor."))
        if pk == "estrategista" and x not in e["aliados"] and casa_op(e, x, "eu") > 48:
            cand.append((1.8, x, "proposta", "Vou ser direto: você e eu juntos chegamos longe. Topa fechar uma aliança?"))
        if pk == "fofoqueira":
            pls = [pl for pl in e["planos"] if pl["alvo"] == "eu" and pl["quem"] in e["parts"]]
            if pls:
                pl = pls[-1]
                cand.append((3, x, "info", f"Escuta... eu ouvi {nm(pl['quem'])} e {nm(pl['com'])} combinando voto em você. Não fala que fui eu!", pl))
            else:
                cand.append((1, x, "info", "Você não sabe o que eu ouvi ontem! Senta aqui que eu te conto tudo."))
        if pk == "manipulador":
            amigos = sorted([y for y in casa_vivos(e, False) if y != x], key=lambda y: -casa_op(e, "eu", y))
            if amigos:
                cand.append((1.6, x, "duvida", f"Cuidado com {nm(amigos[0])}. Já vi falando de você quando você sai do quarto. Só tô te avisando."))
        if r["amz"] < 32 and pk in ("explosivo", "sincero", "arrogante"):
            cand.append((1.8, x, "confronto", "Não vou fingir pra câmera: eu não gosto do seu jogo. E você sabe disso."))
        if e.get("isolado") == x:
            cand.append((2.2, x, "desabafo", "Posso falar com você? Tô me sentindo tão sozinho aqui dentro..." if p["sexo"] == "M" else "Posso falar com você? Tô me sentindo tão sozinha aqui dentro..."))
    if e.get("conselho_sem") != e["semana"] or (e.get("conselho_sem2") != e["semana"] and random.random() < .45):   # até dois pedidos de conselho por semana
        cs = [x for x in casa_vivos(e, False) if casa_op(e, x, "eu") >= 45 and not any(c["pid"] == x for c in e.get("conselhos", []))]
        if cs:
            x = max(cs, key=lambda y: casa_op(e, y, "eu") + random.uniform(0, 15))
            dl_ = casa_dilema(e, x)
            if dl_:
                cand.append((4.5, x, "conselho", dl_[1], dl_[0]))
    casa_abordagem_extra(e, cand)
    casa_abordagem_romance(e, cand)
    if e.setdefault("cotid_sem", {}).get(str(e["semana"]), 0) < 2:   # até dois papos do dia a dia por semana
        cand.append((3.2, random.choice(casa_vivos(e, False)), "cotidiano", "", ""))   # o assunto só é criado se essa abordagem for a escolhida
    rt = casa_retorno_conselho(e) if random.random() < .5 else None
    if rt:
        cand.append((3,) + rt)
    aq = casa_abordagem_quarto(e) if e.get("abord_quarto_sem") != e["semana"] or random.random() < .35 else None
    if aq:
        cand.append((4,) + aq)
    if not cand:
        return
    tot = sum(c[0] for c in cand)
    r0 = random.uniform(0, tot)
    for c in cand:
        r0 -= c[0]
        if r0 <= 0:
            break
    _, pid, tipo, fala, *extra = c
    if tipo == "info" and extra:
        pl = extra[0]
        e["segredos"].append(f"Semana {e['semana']}: {nm(pl['quem'])} e {nm(pl['com'])} combinaram votar em você (contado por {nm(pid)}).")
        casa_mudar(e, pid, "eu", 5, 6)
    if tipo.startswith("q_"):
        e["abord_quarto_sem"] = e["semana"]
    if tipo == "cotidiano":
        pq = casa_pergunta_cotidiano(e, pid)
        if not pq:
            return
        fala, extra = pq[0], [pq[1]]
        cs_ = e.setdefault("cotid_sem", {})
        cs_[str(e["semana"])] = cs_.get(str(e["semana"]), 0) + 1
        e["abordagem"] = dict(pid=pid, tipo=tipo, fala=fala, tema=extra[0] if extra else fala)
        casa_abordagem_cena(e)
        return
    if tipo == "conselho":
        if e.get("conselho_sem") == e["semana"]:
            e["conselho_sem2"] = e["semana"]
        e["conselho_sem"] = e["semana"]
        e["abordagem"] = dict(pid=pid, tipo=tipo, fala=casa_gen(e, f"{J}, posso te pedir um conselho? {fala}", pid), dkey=extra[0] if extra else fala)
        casa_abordagem_cena(e)
        return
    if tipo == "q_desabafo":   # no quarto, de madrugada, um pedaço da história de vida
        kcap = casa_lenda_cap_disponivel(e, pid)
        if kcap:
            fala = casa_lenda_revelar(e, pid, kcap)
    e["abordagem"] = dict(pid=pid, tipo=tipo, fala=casa_variar(e, casa_gen(e, fala, pid), pid))
    ult[pid] = e["semana"]
    e["abord_n"] = e.get("abord_n", 0) + 1
    casa_abordagem_cena(e)


CASA_ABORD_CEN = {"flerte": "flerte", "q_flerte": "flerte", "beijo": "flerte", "satisfacao": "satisfacao", "confronto": "confronto", "deboche": "confronto",
                  "desabafo": "desabafo", "q_desabafo": "quarto", "q_reclama": "quarto", "q_ajuda": "quarto", "conselho": "desabafo"}


def casa_abordagem_cena(e):
    """A abordagem acontece na cena, cara a cara: o agente vai até o participante e fala com ele."""
    a = e.get("abordagem")
    if not a:
        return
    cv = dict(cen=casa_cenario_sortear(e, CASA_CEN_POR_TIPO.get(CASA_ABORD_CEN.get(a["tipo"], ""))), lugar="reality_sala", var=0)
    e["_sem_variar"] = True
    casa_cena_conversa(e, a["pid"], a["fala"], cv, titulo=f"💬 {casa_nome(e, a['pid'])} e {e['jogador']}")
    e["abord_rerun"] = True


def casa_abordagem_ui(e, k):
    a = e.get("abordagem")
    if not a or a["pid"] not in casa_vivos(e, False):
        e.pop("abordagem", None)
        return False
    nm = casa_nome(e, a["pid"])
    if a["tipo"].startswith("q_"):
        return casa_abordagem_quarto_ui(e, k, a, nm)
    if a["tipo"] == "conselho":
        return casa_conselho_ui(e, k, a, nm)
    if a["tipo"] in ("lorota", "gentileza", "deboche"):
        return casa_abordagem_emocao_ui(e, k, a, nm)
    if a["tipo"] == "cotidiano":
        return casa_cotidiano_ui(e, k, a, nm)
    if a["tipo"] == "beijo":
        return casa_beijo_ui(e, k, a, nm)
    st.markdown(f"<div class='casa-card' style='border-color:#00e5ff'>💬 <b>{nm}</b> chega perto de {e['jogador']}: <i>“{a['fala']}”</i></div>", unsafe_allow_html=True)
    c1, c2, c3 = st.columns(3)
    if c1.button("💬 Conversar (não gasta ação)", type="primary", key=k + "abc", use_container_width=True):
        lug = {"flerte": "reality_piscina", "satisfacao": "reality_cozinha", "confronto": "reality_sala", "desabafo": "reality_quarto"}.get(a["tipo"], casa_lugar_rand())
        e["conversa"] = dict(pid=a["pid"], msgs=[("npc", a["fala"])], n=0, lugar=lug, var=random.randrange(3), cen=casa_cenario_sortear(e, CASA_CEN_POR_TIPO.get(a["tipo"])))
        e["_sem_variar"] = True
        if a["tipo"] in ("satisfacao", "confronto"):
            casa_cena(e, lug, [a["pid"]], a["fala"], quem=a["pid"], enc="briga", eu=True, var=e["conversa"]["var"], titulo=f"💬 {nm} e {e['jogador']}")
        else:
            casa_cena_conversa(e, a["pid"], a["fala"], e["conversa"], titulo=f"💬 {nm} e {e['jogador']}")
        e.pop("abordagem", None)
        st.rerun()
