  ctx.fillStyle = '#90caf9'; ctx.beginPath(); ctx.moveTo(-w*.3, -h*.62); ctx.lineTo(-w*.24, -h*.95); ctx.lineTo(w*.24, -h*.95); ctx.lineTo(w*.3, -h*.62); ctx.fill();
