# ---------------------------------------------------------------- 🔍 ACHADOS DA RODOVIÁRIA (objetos escondidos)
ACHADOS_JS = r"""
const W = 480, H = 680, AREA = 540, cv = $('c'), ctx = cv.getContext('2d'); cv.width = W; cv.height = H;
const ITENS = [['🧦', 'a meia listrada'], ['☂️', 'o guarda-chuva'], ['🔑', 'a chave de casa'], ['👓', 'os óculos de leitura'], ['🧸', 'o ursinho'], ['📱', 'o celular'], ['⌚', 'o relógio'],
  ['🎧', 'o fone de ouvido'], ['📕', 'o livro de receitas'], ['🧢', 'o boné'], ['🧤', 'a luva'], ['💍', 'a aliança'], ['🪀', 'o ioiô'], ['🧶', 'o novelo de lã'], ['🕶️', 'os óculos escuros'],
  ['🪥', 'a escova de dentes'], ['🍼', 'a mamadeira'], ['🎒', 'a mochila'], ['👟', 'o tênis'], ['📷', 'a câmera'], ['🔦', 'a lanterna'], ['🪁', 'a pipa'], ['🎀', 'o laço de cabelo'],
  ['🧣', 'o cachecol'], ['💼', 'a maleta'], ['🪭', 'o leque'], ['🧩', 'a peça do quebra-cabeça'], ['🎲', 'o dado da sorte'], ['🖊️', 'a caneta'], ['✂️', 'a tesoura'], ['🎟️', 'o ingresso do show'],
  ['💳', 'o cartão'], ['📿', 'o terço'], ['🪆', 'a boneca'], ['🏓', 'a raquete'], ['⚽', 'a bola'], ['🎺', 'o trompete'], ['🥁', 'o tamborzinho'], ['🧁', 'o bolinho'], ['🍎', 'a maçã'],
  ['🐢', 'a tartaruguinha de pelúcia'], ['🌂', 'a sombrinha'], ['📻', 'o radinho'], ['🧴', 'o protetor solar'], ['🪒', 'o barbeador'], ['🎮', 'o controle do videogame'], ['💄', 'o batom'], ['🪙', 'a moeda da sorte']];
const DONOS = ['Dona Cida', 'Seu Juca', 'a pequena Bia', 'o Tonhão do caminhão', 'a vó Zefa', 'o estudante Caio', 'a enfermeira Lúcia', 'o músico Dedé', 'a turista Ingrid',
  'o Seu Antenor', 'a Dona Neném', 'o menino Davi', 'a noiva Clarinha', 'o pescador Mané'];
const AGRADECE = ['Ai, que alívio! Deus te pague!', 'Achou! Você é um anjo!', 'Eba! Muito obrigado, moço!', 'Nem acredito! Era do meu avô!', 'Que bênção, eu já tinha desistido!', 'Valeu demais!'];
let nivel = 1, objs, alvos, achou, erros, dicas, t0, msg = '', msgT = 0, efeitos = [], rodando = false, piscar = null;
function montar(){ const n = 70 + nivel*22, pool = embaralhar(ITENS.slice()); alvos = pool.slice(0, 6).map((it, i) => ({e: it[0], nome: it[1], dono: DONOS[(nivel*3 + i) % DONOS.length], ok: false}));
  objs = []; const enfeite = pool.slice(6);
  for (let i = 0; i < n; i++) { const it = enfeite[i % enfeite.length]; objs.push({e: it[0], x: 20 + Math.random()*(W - 40), y: 70 + Math.random()*(AREA - 90), s: 24 + Math.random()*24, r: (Math.random() - .5)*1.4, alvo: -1}); }
  alvos.forEach((a, i) => { const pos = Math.floor(objs.length*(.35 + Math.random()*.45)); objs.splice(pos, 0, {e: a.e, x: 30 + Math.random()*(W - 60), y: 80 + Math.random()*(AREA - 110), s: 26 + Math.random()*10, r: (Math.random() - .5)*1.2, alvo: i}); });
  achou = 0; erros = 0; dicas = 3; t0 = performance.now(); msg = `${alvos[0].dono} chegou no balcão: “Perdi ${alvos[0].nome}!”`; msgT = 4; rodando = true; tela(''); }
function clique(ev){ if (!rodando) return; audio(); const r = cv.getBoundingClientRect(), mx = (ev.clientX - r.left)*W/r.width, my = (ev.clientY - r.top)*H/r.height;
  if (my > AREA) { if (mx > W - 120 && my > AREA + 90) dica(); return; }
  for (let i = objs.length - 1; i >= 0; i--) { const o = objs[i]; if (Math.hypot(o.x - mx, o.y - my) < o.s*.5) {
      if (o.alvo >= 0 && !alvos[o.alvo].ok) { const a = alvos[o.alvo]; a.ok = true; achou++; objs.splice(i, 1); efeitos.push({x: o.x, y: o.y, t: 1, e: o.e}); acorde([523, 659, 784]);
        msg = `${a.dono}: “${AGRADECE[(achou + nivel) % AGRADECE.length]}”`; msgT = 3; piscar = null;
        if (achou === alvos.length) concluir(); else { const p = alvos.find(x => !x.ok); setTimeout(() => { if (rodando) { msg = `${p.dono} está no balcão: “Alguém viu ${p.nome}?”`; msgT = 4; } }, 1600); }
        return; }
      erros++; bip(180, .08, 'square', .03); efeitos.push({x: o.x, y: o.y, t: .5, e: '✖'}); return; } } }
cv.addEventListener('pointerdown', clique);
function dica(){ if (!dicas || !rodando) return; const i = alvos.findIndex(a => !a.ok); if (i < 0) return; dicas--; piscar = objs.find(o => o.alvo === i); bip(880, .2, 'sine', .05); }
function concluir(){ rodando = false; const seg = (performance.now() - t0)/1000, est = 1 + (seg < 60 + nivel*10 ? 1 : 0) + (erros < 4 ? 1 : 0);
  const rec = salvarRecorde('achados_nivel', nivel); acorde([523, 659, 784, 1046], .18); nivel++;
  tela(`<h1>📦 Balcão vazio!</h1><p class='grande'>${'⭐'.repeat(est)}${'☆'.repeat(3 - est)}</p><p>Você devolveu tudo em ${fmtTempo(seg)} com ${erros} toque(s) errado(s).</p>
    <p>O próximo ônibus chega com mais bagunça...</p><button onclick='montar()'>🚌 Abrir o nível ${nivel}</button>`); }
function desenhar(){
  ctx.fillStyle = '#5d4037'; ctx.fillRect(0, 0, W, H); ctx.fillStyle = '#8d6e63'; for (let y = 60; y < AREA; y += 120) ctx.fillRect(0, y + 100, W, 12);
  ctx.fillStyle = '#d7ccc8'; ctx.fillRect(0, 0, W, 58); ctx.fillStyle = '#3e2723'; ctx.font = 'bold 16px system-ui'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('🚌 ACHADOS E PERDIDOS DA RODOVIÁRIA · nível ' + nivel, W/2, 18); ctx.font = '13px system-ui'; ctx.fillText(msg, W/2, 42);
  for (const o of objs) { ctx.save(); ctx.translate(o.x, o.y); ctx.rotate(o.r); ctx.font = o.s + 'px serif'; ctx.fillText(o.e, 0, 0); ctx.restore(); }
  if (piscar) { const p = (Math.sin(performance.now()/120) + 1)/2; ctx.strokeStyle = `rgba(255,235,59,${.4 + p*.6})`; ctx.lineWidth = 4; ctx.beginPath(); ctx.arc(piscar.x, piscar.y, piscar.s*.75 + p*6, 0, 7); ctx.stroke(); }
  for (const f of efeitos) { ctx.globalAlpha = Math.max(0, f.t); ctx.font = (f.e === '✖' ? 26 : 34 + (1 - f.t)*40) + 'px serif'; ctx.fillStyle = '#ff5252'; ctx.fillText(f.e, f.x, f.y - (1 - f.t)*40); }
  ctx.globalAlpha = 1; efeitos = efeitos.filter(f => (f.t -= .02) > 0);
  ctx.fillStyle = '#fff8e1'; ctx.fillRect(0, AREA, W, H - AREA); ctx.fillStyle = '#5d4037'; ctx.font = 'bold 13px system-ui'; ctx.textAlign = 'left'; ctx.fillText('Procure no balcão:', 10, AREA + 16);
  alvos.forEach((a, i) => { const x = 10 + (i % 3)*155, y = AREA + 42 + Math.floor(i/3)*40; ctx.globalAlpha = a.ok ? .35 : 1; ctx.font = '26px serif'; ctx.fillText(a.e, x, y);
    ctx.font = '12px system-ui'; ctx.fillStyle = '#4e342e'; ctx.fillText(a.ok ? '✅ devolvido' : a.dono.replace(/^(a |o )/, ''), x + 32, y); ctx.globalAlpha = 1; });
  ctx.fillStyle = dicas ? '#ffb300' : '#bdbdbd'; ctx.fillRect(W - 116, AREA + 96, 106, 36); ctx.fillStyle = '#fff'; ctx.font = 'bold 14px system-ui'; ctx.textAlign = 'center';
  ctx.fillText('💡 Dica (' + dicas + ')', W - 63, AREA + 115);
  if (rodando) { ctx.textAlign = 'left'; ctx.fillStyle = '#6d4c41'; ctx.font = '12px system-ui'; ctx.fillText('⏱️ ' + fmtTempo((performance.now() - t0)/1000), 10, AREA + 120); }
}
function loop(){ desenhar(); requestAnimationFrame(loop); }
alvos = []; objs = []; msg = '';
tela(`<h1>🔍 Achados da Rodoviária</h1><p>Você cuida do balcão de achados e perdidos. Os donos chegam aflitos: encontre cada objeto no meio da bagunça e devolva.</p>
  <p>Toque no objeto certo. Sem pressa: aqui ninguém perde, só ganha estrela. Travou? Use a <b>💡 dica</b>.</p><p>Maior nível: ${lerRecorde('achados_nivel')}</p><button onclick='audio(); montar()'>📦 Abrir o balcão</button>`);
requestAnimationFrame(loop);
"""

# ---------------------------------------------------------------- 🔦 PLANTÃO NOTURNO (suspense com lanterna)
PLANTAO_JS = CONTROLES_JS + r"""
const W = 480, H = 640, T = 32, CO = 15, LI = 19, TOP = 32, cv = $('c'), ctx = cv.getContext('2d'); cv.width = W; cv.height = H;
const esc = document.createElement('canvas'); esc.width = W; esc.height = H; const ec = esc.getContext('2d');
let mapa, eu, sombras, fus, bats, porta, nivel = 1, coragem, bateria, lant, rodando = false, ang = 0, bat = 0, rec = lerRecorde('plantao_rec');
const parede = (x, y) => x < 0 || y < 0 || x >= CO || y >= LI || mapa[y][x] === 1;
function labirinto(){ mapa = Array.from({length: LI}, () => Array(CO).fill(1)); const pilha = [[1, 1]]; mapa[1][1] = 0;
  while (pilha.length) { const [x, y] = pilha[pilha.length - 1]; const viz = embaralhar([[2, 0], [-2, 0], [0, 2], [0, -2]]).filter(([dx, dy]) => x + dx > 0 && y + dy > 0 && x + dx < CO - 1 && y + dy < LI - 1 && mapa[y + dy][x + dx]);
    if (!viz.length) { pilha.pop(); continue; } const [dx, dy] = viz[0]; mapa[y + dy/2][x + dx/2] = 0; mapa[y + dy][x + dx] = 0; pilha.push([x + dx, y + dy]); }
  for (let i = 0; i < 26; i++) { const x = 1 + Math.floor(Math.random()*(CO - 2)), y = 1 + Math.floor(Math.random()*(LI - 2)); if ((x + y) % 2) mapa[y][x] = 0; } }
function celulas(){ const l = []; for (let y = 1; y < LI - 1; y++) for (let x = 1; x < CO - 1; x++) if (!mapa[y][x]) l.push([x, y]); return l; }
function iniciar(){ labirinto(); const cel = embaralhar(celulas()).filter(([x, y]) => x + y > 8);
  eu = {x: 1.5, y: 1.5}; porta = {x: CO - 2 + .5, y: LI - 2 + .5}; mapa[LI - 2][CO - 2] = 0;
  fus = cel.slice(0, 3).map(([x, y]) => ({x: x + .5, y: y + .5, ok: false})); bats = cel.slice(3, 5).map(([x, y]) => ({x: x + .5, y: y + .5, ok: false}));
  sombras = cel.slice(5, 7 + nivel).filter(([x, y]) => x + y > 12).map(([x, y]) => ({x: x + .5, y: y + .5, vx: 0, vy: 0, t: 0, medo: 0}));
  bateria = 100; lant = true; rodando = true; tela(''); }
function novo(){ nivel = 1; coragem = 3; iniciar(); }
function tecla(k){ if (!rodando) return; if (k === 'f' || k === ' ' || k === 'luz') { lant = !lant; bip(lant ? 900 : 500, .04, 'square', .03); } }
function mover(o, dx, dy, r){ if (!parede(Math.floor(o.x + dx + Math.sign(dx)*r), Math.floor(o.y))) o.x += dx; if (!parede(Math.floor(o.x), Math.floor(o.y + dy + Math.sign(dy)*r))) o.y += dy; }
function iluminado(o){ if (!lant || bateria <= 0) return false; const dx = o.x - eu.x, dy = o.y - eu.y, d = Math.hypot(dx, dy); if (d > 5.5) return false;
  let da = Math.atan2(dy, dx) - ang; da = Math.atan2(Math.sin(da), Math.cos(da)); if (Math.abs(da) > .5) return false;
  for (let k = .3; k < d; k += .3) if (parede(Math.floor(eu.x + dx/d*k), Math.floor(eu.y + dy/d*k))) return false; return true; }
function passo(dt){
  let mx = (dir() ? 1 : 0) - (esq() ? 1 : 0), my = (baixo() ? 1 : 0) - (cima() ? 1 : 0); const l = Math.hypot(mx, my) || 1;
  if (mx || my) { const alvo = Math.atan2(my, mx); let d = alvo - ang; d = Math.atan2(Math.sin(d), Math.cos(d)); ang += d*Math.min(1, dt*12); }
  mover(eu, mx/l*3*dt, my/l*3*dt, .28);
  if (lant) bateria = Math.max(0, bateria - 3.2*dt); let perto = 99;
  for (const s of sombras) { const dx = eu.x - s.x, dy = eu.y - s.y, d = Math.hypot(dx, dy); perto = Math.min(perto, d);
    if (iluminado(s)) { s.medo = 1.2; s.vx = -dx/d*2.6; s.vy = -dy/d*2.6; }
    else if (s.medo > 0) s.medo -= dt;
    else if (d < 6.5) { s.vx = dx/d*(1.45 + nivel*.12); s.vy = dy/d*(1.45 + nivel*.12); }
    else { s.t -= dt; if (s.t <= 0) { const a = Math.random()*7; s.vx = Math.cos(a); s.vy = Math.sin(a); s.t = 1.5; } }
    mover(s, s.vx*dt, s.vy*dt, .25);
    if (d < .55) { coragem--; ruido(.5, .22); bip(120, .5, 'sawtooth', .08, -60); vibrar(250); const c = embaralhar(celulas())[0]; s.x = c[0] + .5; s.y = c[1] + .5; s.medo = 2;
      if (coragem <= 0) return fim(false); } }
  bat -= dt; if (perto < 4.5 && bat <= 0) { bip(60, .12, 'sine', .14); setTimeout(() => bip(55, .1, 'sine', .1), 140); bat = .3 + perto*.22; }
  for (const f of fus) if (!f.ok && Math.hypot(f.x - eu.x, f.y - eu.y) < .5) { f.ok = true; acorde([392, 523]); }
  for (const b of bats) if (!b.ok && Math.hypot(b.x - eu.x, b.y - eu.y) < .5) { b.ok = true; bateria = Math.min(100, bateria + 45); acorde([659, 880]); }
  if (fus.every(f => f.ok) && Math.hypot(porta.x - eu.x, porta.y - eu.y) < .55) { nivel++; rec = salvarRecorde('plantao_rec', nivel - 1); acorde([523, 659, 784, 1046], .16); rodando = false;
    tela(`<h1>💡 A luz voltou na ala ${nivel - 1}!</h1><p>Você sobreviveu ao andar. Mas o elevador só desce...</p><p>Coragem: ${'💛'.repeat(coragem)}</p><button onclick='iniciar()'>🛗 Descer para o andar ${nivel}</button>`); }
}
function fim(){ rodando = false; rec = salvarRecorde('plantao_rec', nivel - 1);
  tela(`<h1>😱 Você correu para fora!</h1><p class='grande'>Andares vencidos: ${nivel - 1}</p><p>Recorde: ${rec}</p><button onclick='novo()'>🔦 Voltar ao plantão</button>`); }
const px = x => x*T, py = y => TOP + y*T;
function desenhar(){
  ctx.fillStyle = '#0b0e14'; ctx.fillRect(0, 0, W, H);
  for (let y = 0; y < LI; y++) for (let x = 0; x < CO; x++) { if (mapa[y][x]) { ctx.fillStyle = '#5c6b73'; ctx.fillRect(px(x), py(y), T, T); ctx.fillStyle = '#4a575e'; ctx.fillRect(px(x), py(y) + T - 6, T, 6); }
    else { ctx.fillStyle = (x + y) % 2 ? '#c8d0c4' : '#bcc5b8'; ctx.fillRect(px(x), py(y), T, T); } }
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.font = '20px serif';
  ctx.fillText(fus.every(f => f.ok) ? '🚪' : '🔒', px(porta.x), py(porta.y));
  for (const f of fus) if (!f.ok) ctx.fillText('🔌', px(f.x), py(f.y)); for (const b of bats) if (!b.ok) ctx.fillText('🔋', px(b.x), py(b.y));
  for (const s of sombras) { const x = px(s.x), y = py(s.y), tt = performance.now()/200;
    ctx.fillStyle = 'rgba(20,10,30,.92)'; ctx.beginPath(); ctx.moveTo(x - 11, y + 13); ctx.quadraticCurveTo(x - 13, y - 16, x, y - 16); ctx.quadraticCurveTo(x + 13, y - 16, x + 11, y + 13);
    for (let i = 0; i < 4; i++) ctx.lineTo(x + 11 - i*7.3 - 3.6, y + 13 - (i % 2 ? 0 : 5 + Math.sin(tt + i)*2)); ctx.fill();
    ctx.fillStyle = s.medo > 0 ? '#80deea' : '#ff1744'; ctx.fillRect(x - 6, y - 7, 4, 3); ctx.fillRect(x + 2, y - 7, 4, 3); }
  ctx.fillStyle = '#fff3e0'; ctx.beginPath(); ctx.arc(px(eu.x), py(eu.y), 9, 0, 7); ctx.fill(); ctx.fillStyle = '#4fc3f7'; ctx.beginPath(); ctx.arc(px(eu.x), py(eu.y), 6, 0, 7); ctx.fill();
  // escuridão: só a lanterna e um brilho fraco em volta
  ec.globalCompositeOperation = 'source-over'; ec.fillStyle = 'rgba(0,0,0,.965)'; ec.fillRect(0, 0, W, H); ec.globalCompositeOperation = 'destination-out';
  const cx = px(eu.x), cy = py(eu.y); let gr = ec.createRadialGradient(cx, cy, 4, cx, cy, 52); gr.addColorStop(0, 'rgba(0,0,0,.85)'); gr.addColorStop(1, 'rgba(0,0,0,0)'); ec.fillStyle = gr; ec.beginPath(); ec.arc(cx, cy, 52, 0, 7); ec.fill();
  if (lant && bateria > 0) { const alc = 176*(bateria < 15 ? .6 + Math.random()*.4 : 1); gr = ec.createRadialGradient(cx, cy, 10, cx, cy, alc); gr.addColorStop(0, 'rgba(0,0,0,1)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
    ec.fillStyle = gr; ec.beginPath(); ec.moveTo(cx, cy); ec.arc(cx, cy, alc, ang - .5, ang + .5); ec.closePath(); ec.fill(); }
  ctx.drawImage(esc, 0, 0);
  ctx.fillStyle = 'rgba(0,0,0,.7)'; ctx.fillRect(0, 0, W, TOP); ctx.fillStyle = '#fff'; ctx.font = 'bold 14px system-ui'; ctx.textAlign = 'left';
  ctx.fillText('💛'.repeat(Math.max(0, coragem)) + '   🔌 ' + fus.filter(f => f.ok).length + '/3   Andar ' + nivel, 8, 17);
  ctx.fillStyle = '#333'; ctx.fillRect(W - 120, 9, 100, 13); ctx.fillStyle = bateria > 25 ? '#ffee58' : '#ff5252'; ctx.fillRect(W - 120, 9, bateria, 13); ctx.fillStyle = '#fff'; ctx.fillText(lant ? '🔦' : '🌑', W - 18, 17);
}
let ult = performance.now();
function loop(t){ const dt = Math.min(.05, (t - ult)/1000); ult = t; if (rodando) passo(dt); if (mapa) desenhar(); requestAnimationFrame(loop); }
coragem = 3; labirinto(); eu = {x: 1.5, y: 1.5}; fus = []; bats = []; sombras = []; porta = {x: CO - 1.5, y: LI - 1.5}; bateria = 100; lant = true;
tela(`<h1>🔦 Plantão Noturno</h1><p>A luz caiu no hospital e você ficou de plantão. Ache os <b>3 fusíveis 🔌</b> para religar a energia e saia pela porta 🚪.</p>
  <p>As <b>sombras</b> não gostam de luz: aponte a lanterna para elas recuarem. Mas a bateria acaba... pegue as pilhas 🔋. <b>F / 🔦</b> liga e desliga.</p>
  <p>Use fone de ouvido: o coração acelera quando elas chegam perto.</p><p>Recorde: ${rec} andar(es)</p><button onclick='audio(); novo()'>🔦 Começar o plantão</button>`);
requestAnimationFrame(loop);
"""


