LIG_MAX = 12


def lig_nova_alma():
    if S.get("groq_key"):
        try:
            d = json.loads(groq_chat([{"role": "system", "content":
                "Crie uma pessoa brasileira idosa, comum e encantadora, que acabou de partir em paz, de velhice, dormindo (nada de violência, doença longa ou tragédia). "
                "Ela liga para a 'Central das Lembranças' sem lembrar da própria vida. Dê a ela 3 memórias marcantes, simples e concretas, de temas DIFERENTES "
                "(por exemplo: trabalho, um amor, a infância, um lugar, uma festa, um bicho de estimação). Responda SOMENTE JSON: "
                "{\"nome\": \"Dona ... / Seu ...\", \"idade\": 80, \"de\": \"cidade, estado por extenso\", \"oficio\": \"...\", \"jeito\": \"jeito de falar\", "
                "\"primeira_fala\": \"o que diz ao atender, confusa e doce, sem dizer o nome\", "
                "\"memorias\": [{\"titulo\": \"2 a 4 palavras\", \"tema\": \"palavras-chave do tema\", \"gatilhos\": [\"6 a 8 radicais de palavras que puxam essa memória\"], "
                "\"lembranca\": \"a lembrança contada em primeira pessoa, 1 ou 2 frases, com um detalhe sensorial\"}]}"},
                {"role": "user", "content": f"Pessoa número {random.randint(1, 99999)}. Varie região do Brasil, sexo e profissão."}], json_mode=True))
            ms = [dict(titulo=str(m["titulo"])[:40], tema=str(m["tema"])[:80], gatilhos=[str(g).lower()[:15] for g in m.get("gatilhos", [])][:8], lembranca=str(m["lembranca"])[:300])
                  for m in d["memorias"][:3]]
            if len(ms) == 3 and d.get("nome"):
                return dict(nome=str(d["nome"])[:30], idade=int(d.get("idade", 80)), de=str(d.get("de", "Brasil"))[:50], oficio=str(d.get("oficio", ""))[:40],
                            jeito=str(d.get("jeito", ""))[:100], primeira_fala=str(d.get("primeira_fala", "Alô? Quem fala?"))[:240], memorias=ms)
        except Exception:
            pass
    usadas = S.setdefault("lig_usadas", [])
    livres = [a for a in LIG_ALMAS if a["nome"] not in usadas] or LIG_ALMAS
    a = random.choice(livres)
    usadas.append(a["nome"])
    return dict(a)


def lig_responder(lg, msg):
    a = lg["alma"]
    faltam = [i for i in range(3) if i not in lg["lembradas"]]
    lembrou, fala = [], None
    if S.get("groq_key"):
        try:
            mem = "\n".join(f"{i}: tema [{a['memorias'][i]['tema']}] -> lembrança: {a['memorias'][i]['lembranca']}" for i in faltam)
            msgs = [{"role": "system", "content":
                f"Você é {a['nome']}, {a['idade']} anos, {a['oficio']}, de {a['de']}. Jeito: {a['jeito']}. Você partiu em paz e está ao telefone com a operadora da Central das Lembranças, "
                "que te ajuda a lembrar quem você foi. Você está confusa, doce, sem medo. Fale como gente, 1 a 3 frases curtas, em português do Brasil.\n"
                f"MEMÓRIAS AINDA ESQUECIDAS (só você e o sistema sabem; NUNCA conte sem ser puxada):\n{mem}\n"
                "Se a última fala da operadora tocar no TEMA de uma memória (uma pergunta ou um comentário sobre aquele assunto), você lembra: conte essa lembrança com emoção, "
                "usando as palavras dela, e coloque o número em 'lembrou'. Se não tocar em nenhum tema, responda com carinho, diga que ainda não lembra e dê uma pista vaga "
                "de um tema (um cheiro, um som, uma sensação), sem contar a memória. Responda SOMENTE JSON: {\"fala\": \"...\", \"lembrou\": []}"}]
            for r0, t0 in lg["msgs"][-8:]:
                msgs.append({"role": "user" if r0 == "user" else "assistant", "content": t0 if r0 == "user" else json.dumps({"fala": t0}, ensure_ascii=False)})
            d = json.loads(groq_chat(msgs, json_mode=True))
            fala = str(d.get("fala", "")).strip()[:500]
            lembrou = [int(i) for i in d.get("lembrou", []) if int(i) in faltam][:1]
        except Exception:
            fala = None
    if not fala:
        t = msg.lower()
        for i in faltam:
            if any(g in t for g in a["memorias"][i]["gatilhos"]):
                lembrou = [i]
                break
        if lembrou:
            fala = a["memorias"][lembrou[0]]["lembranca"]
        else:
            pistas = [f"Hum... não sei. Mas me vem um cheiro de {random.choice(['café passado', 'chuva na terra', 'bolo no forno', 'mar', 'roupa limpa no varal'])}...",
                      "Ainda não lembro... mas parece que tem uma música tocando bem longe.", "Não sei, meu bem. Pergunta de outro jeito? Do que a gente sente saudade...",
                      "Tá tudo embaralhado. Mas minhas mãos parecem que lembram de alguma coisa..."]
            fala = random.choice(pistas)
    lg["msgs"].append(("npc", fala))
    for i in lembrou:
        lg["lembradas"].append(i)
        lg["ultima"] = i


def lig_adeus(lg, txt):
    a = lg["alma"]
    nota, fala = None, None
    if S.get("groq_key"):
        try:
            d = json.loads(groq_chat([{"role": "system", "content":
                f"Você é {a['nome']}, que partiu em paz e lembrou de parte da vida ({', '.join(a['memorias'][i]['titulo'] for i in lg['lembradas']) or 'quase nada'}). "
                "A operadora se despede de você. Dê uma nota de 0 a 10 para o carinho e o acolhimento da despedida, e responda com as suas últimas palavras, 1 ou 2 frases, "
                "em paz e gratidão. Responda SOMENTE JSON: {\"nota\": 0, \"fala\": \"...\"}"}, {"role": "user", "content": txt[:400]}], json_mode=True))
            nota = max(0, min(10, int(d.get("nota", 6))))
            fala = str(d.get("fala", "")).strip()[:300]
        except Exception:
            pass
    if nota is None:
        t = txt.lower()
        nota = min(10, 4 + len(txt)//40 + sum(2 for w in ("paz", "obrigad", "amor", "lembr", "saudade", "descans", "luz", "bonit", "orgulho") if w in t))
        fala = random.choice(["Obrigada por me lembrar de quem eu fui. Agora eu posso ir tranquila.", "Que voz boa a sua. Vou levar ela comigo. Fica com Deus.",
                              "Eu tô indo, mas indo inteira. Muito obrigado, de coração."])
    lg.update(fase="fim", nota=nota, ult_fala=fala)
    pts = len(lg["lembradas"])*30 + max(0, LIG_MAX - lg["perguntas"])*4 + nota*3
    lg["pontos"] = pts
    S["lig_rec"] = max(S.get("lig_rec", 0), pts)


def jogo_ligacao():
    st.markdown("""<style>.lig{background:linear-gradient(160deg,#1b1530,#0f2b3a);border:1px solid #6d5dfc55;border-radius:16px;padding:14px 16px;color:#eee}
.lig h3{margin:0 0 4px;color:#ffd7a8}.foto{border-radius:10px;padding:10px;text-align:center;min-height:118px;font-size:.86rem}
.foto.on{background:#fff8e7;color:#3e2723;box-shadow:0 4px 14px #0006;transform:rotate(-1.5deg)}.foto.off{background:#ffffff10;border:1px dashed #ffffff40;color:#aaa;filter:blur(.3px)}</style>""",
                unsafe_allow_html=True)
    lg = S.get("lig")
    if not lg:
        st.markdown("<div class='lig'><h3>☎️ A Última Ligação</h3>Você trabalha no turno da noite da <b>Central das Lembranças</b>. O telefone toca: do outro lado está alguém que "
                    "acabou de partir, em paz, mas esqueceu quem foi.<br><br>Converse com carinho e faça as perguntas certas para despertar <b>3 lembranças</b> da vida dessa pessoa, "
                    f"em até {LIG_MAX} falas. No fim, faça a despedida.</div>", unsafe_allow_html=True)
        if S.get("lig_rec"):
            st.caption(f"🏅 Seu recorde: {S['lig_rec']} pontos")
        if st.button("📞 Atender a ligação", type="primary", key="lig_ini"):
            with st.spinner("O telefone está tocando..."):
                a = lig_nova_alma()
            S["lig"] = dict(alma=a, msgs=[("npc", a["primeira_fala"])], lembradas=[], perguntas=0, fase="conversa")
            st.rerun()
        return
    a = lg["alma"]
    st.markdown(f"<div class='lig'><h3>☎️ Na linha: {a['nome'] if lg['lembradas'] else 'uma voz desconhecida'}</h3>"
                f"{'🕯️ ' + str(a['idade']) + ' anos, ' + a['oficio'] + ', de ' + a['de'] if len(lg['lembradas']) >= 2 else 'Quem será? Pergunte com jeito.'}"
                f"<br><span style='opacity:.75'>Falas usadas: {lg['perguntas']}/{LIG_MAX} · Lembranças: {len(lg['lembradas'])}/3</span></div>", unsafe_allow_html=True)
    cols = st.columns(3)
    for i, m in enumerate(a["memorias"]):
        ok = i in lg["lembradas"]
        cols[i].markdown(f"<div class='foto {'on' if ok else 'off'}'>{'📸 <b>' + _html.escape(m['titulo']) + '</b><br>' + _html.escape(m['lembranca']) if ok else '🌫️<br>Lembrança esquecida'}</div>",
                         unsafe_allow_html=True)
    for r0, t0 in lg["msgs"]:
        with st.chat_message("user" if r0 == "user" else "assistant", avatar="🎧" if r0 == "user" else "☎️"):
            st.markdown(t0)
    if lg["fase"] == "conversa":
        if len(lg["lembradas"]) >= 3 or lg["perguntas"] >= LIG_MAX:
            lg["fase"] = "adeus"
            st.rerun()
        falado = microfone(f"lig_mic{lg['perguntas']}", "🎤 Fale com a pessoa: toque no microfone, fale e toque de novo")
        with st.form(f"lig_f{lg['perguntas']}", clear_on_submit=True):
            msg = st.text_input("Sua fala", placeholder="Com o que a senhora trabalhava? / Tinha alguém especial?", max_chars=300)
            env = st.form_submit_button("📞 Falar", type="primary")
        txt = falado or (msg.strip() if env and msg else "")
        if txt:
            lg["msgs"].append(("user", txt))
            lg["perguntas"] += 1
            with st.spinner("A pessoa está pensando..."):
                lig_responder(lg, txt)
            if "ultima" in lg:
                st.toast(f"📸 Lembrou: {a['memorias'][lg.pop('ultima')]['titulo']}!")
            st.rerun()
        st.caption("💡 Dica: pergunte sobre trabalho, amor, família, infância, lugares, festas... cada lembrança tem um tema.")
    elif lg["fase"] == "adeus":
        st.info(f"{'🌟 Você despertou as 3 lembranças!' if len(lg['lembradas']) == 3 else '⏳ A ligação está chegando ao fim.'} Agora, a despedida: diga algo para "
                f"{a['nome'] if lg['lembradas'] else 'essa pessoa'} seguir em paz.")
        with st.form("lig_adeus"):
            txt = st.text_area("Suas últimas palavras", max_chars=400, height=90, placeholder="Vai em paz...")
            if st.form_submit_button("🕊️ Despedir", type="primary") and txt.strip():
                with st.spinner("..."):
                    lig_adeus(lg, txt.strip())
                st.rerun()
    else:
        st.markdown(f"> ☎️ *{lg['ult_fala']}*")
        st.success(f"🕊️ A ligação terminou. **{lg['pontos']} pontos** · lembranças {len(lg['lembradas'])}/3 · falas usadas {lg['perguntas']} · acolhimento {lg['nota']}/10")
        if st.button("📞 Atender a próxima ligação", type="primary", key="lig_prox"):
            S.pop("lig", None)
            st.rerun()


